# ══════════════════════════════════════════════════════════
# MAIN
# ══════════════════════════════════════════════════════════
def build_questions():
    qs = []
    def add(lst, subject, grade, difficulty):
        for q in lst:
            qs.append(dict(subject=subject,grade=grade,difficulty=difficulty,
                           topic=q["topic"],subTopic=q["subTopic"],
                           questionText=q["questionText"],options=q["options"],
                           correctAnswer=q["correct"],explanation=q["explanation"]))
    add(GK6_ADV,  "General Knowledge", 6, "Advanced")
    add(GK6_OLY,  "General Knowledge", 6, "Olympiad")
    add(GK7_ADV,  "General Knowledge", 7, "Advanced")
    add(GK7_OLY,  "General Knowledge", 7, "Olympiad")
    add(GK8_OLY,  "General Knowledge", 8, "Olympiad")
    add(LR6_OLY,  "Logical Reasoning", 6, "Olympiad")
    add(LR7_OLY,  "Logical Reasoning", 7, "Olympiad")
    add(LR9_OLY,  "Logical Reasoning", 9, "Olympiad")
    add(MATH6_OLY,"Mathematics",       6, "Olympiad")
    return qs

def main():
    conn = pyodbc.connect(DB_CONN)
    questions = build_questions()
    ok = dup = err = 0
    for i, q in enumerate(questions, 1):
        try:
            res = insert(conn, q)
        except Exception as e:
            res = f"ERR: {e}"
        m = "✓" if res=="OK" else ("~" if res=="DUP" else "✗")
        print(f"  {m} Q{i:03d} [{q['subject']} G{q['grade']} {q['difficulty']}] {q['subTopic'][:45]} → {res}")
        if res=="OK": ok+=1
        elif res=="DUP": dup+=1
        else: err+=1
    conn.close()
    print(f"\n  Done: {ok} posted, {dup} duplicates, {err} errors  (total={ok+dup+err})")

if __name__ == "__main__":
    main()
